import type { Coffee, BrewOptions } from "./types";

/** 把阅读代码的时间，留给一杯咖啡。 */
export function brew(options: BrewOptions): Coffee {
  const { beans, water, temperature = 92 } = options;
  const ratio = water / beans;

  return {
    name: ratio > 15 ? "轻盈手冲" : "浓郁一杯",
    temperature,
    ready: temperature >= 85,
  };
}

export interface BrewOptions {
  beans: number;
  water: number;
  temperature?: number;
}

export interface Coffee {
  name: string;
  temperature: number;
  ready: boolean;
}
